using ScrapperTrade.Application;using ScrapperTrade.Domain;using ScrapperTrade.Infrastructure;using ScrapperTrade.Quant;
var tests=new List<(string,Action)>{("sizing metal metadata",Sizing),("undersized rejects",SizingRejects),("real execution impossible",RealRejected),("duplicate rejects",Duplicate),("stale rejects",Stale),("group exposure rejects",Group),("emergency user unlock",Emergency),("state transition safety",StateTransitions),("automation cannot allow instrument",InstrumentAuthority),("unsafe spec rejects",Spec),("ambiguous bars conservative",Backtest)};tests.AddRange(Mt5BridgeDeterministicChecks.All());tests.AddRange(MarketIntelligenceChecks.All());var failures=new List<string>();foreach(var x in tests)try{x.Item2();Console.WriteLine($"PASS {x.Item1}");}catch(Exception e){failures.Add($"FAIL {x.Item1}: {e.Message}");}foreach(var f in failures)Console.Error.WriteLine(f);return failures.Count==0?0:1;
static void Eq<T>(T e,T a)where T:notnull{if(!EqualityComparer<T>.Default.Equals(e,a))throw new Exception($"Expected {e}, got {a}");}static SymbolMetadata Gold()=>new("XAUUSD",.01m,1m,100m,.01m,100m,.01m);static CandidateTrade Trade(DateTimeOffset? at=null)=>new(Guid.NewGuid(),"trend",1,"XAUUSD",Side.Buy,2000,1990,2020,.2m,at??DateTimeOffset.UtcNow);
static void Sizing(){var r=PositionSizer.Calculate(100,2000,1990,Gold());Eq(true,r.Success);Eq(.1m,r.Volume);Eq(100m,r.ActualRisk);}static void SizingRejects()=>Eq(false,PositionSizer.Calculate(1,2000,1990,Gold()).Success);static void RealRejected()=>Eq("DEMO_ONLY",new DemoExecutionSimulator(AccountKind.Real).Execute(new(Guid.NewGuid(),Trade(),.1m,DateTimeOffset.UtcNow)).Code);static void Duplicate(){var a=new DemoExecutionSimulator(AccountKind.Demo);var r=new ExecutionRequest(Guid.NewGuid(),Trade(),.1m,DateTimeOffset.UtcNow);Eq(true,a.Execute(r).Accepted);Eq("DUPLICATE",a.Execute(r).Code);}static void Stale()=>Eq("STALE_DATA",new PortfolioRiskEngine(new()).Evaluate(Trade(DateTimeOffset.UtcNow.AddMinutes(-2)),Gold(),new(10000,0,[]),"METALS",DateTimeOffset.UtcNow).Code);
static void Group(){var p=new RiskPolicy(MaxGroupRiskFraction:.005m);var o=new OpenPosition(Guid.NewGuid(),"XAGUSD",Side.Buy,1,.9m,.1m,1,"METALS",DateTimeOffset.UtcNow);Eq("GROUP_RISK",new PortfolioRiskEngine(p).Evaluate(Trade(),Gold(),new(10000,0,[o]),"METALS",DateTimeOffset.UtcNow).Code);}static void Emergency(){var s=new TradingSystemState();s.Start();s.EmergencyLock();try{s.Start();throw new Exception("start should fail");}catch(InvalidOperationException){}s.UserUnlockToPaused();Eq(SystemMode.Paused,s.Mode);}static void Spec(){var s=new StrategySpec("",0,20,10,0,.5m,new HashSet<MarketRegime>{MarketRegime.Unknown});if(StrategyValidator.Validate(s).Count<4)throw new Exception("expected errors");}
static void StateTransitions(){var s=new SystemStateMachine();var now=DateTimeOffset.UtcNow;s.Start(now);s.EmergencyLock(now,"operator test");try{s.Start(now);throw new Exception("locked start should fail");}catch(InvalidOperationException){}s.UserUnlockToPaused(now,"operator unlock");Eq(SystemMode.Paused,s.Snapshot.Mode);Eq(false,s.Snapshot.AllowsNewEntries);}
static void InstrumentAuthority(){var i=new TradingInstrument("XAUUSD",false,"XAUUSD");try{i.SetAutomatedAvailability(InstrumentAvailability.Active);throw new Exception("automation enabled disallowed instrument");}catch(InvalidOperationException){}var allowed=i.SetUserPermission(true).SetAutomatedAvailability(InstrumentAvailability.Active);Eq(true,allowed.CanOpenNewPosition);var disabled=allowed.SetUserPermission(false);Eq(false,disabled.CanOpenNewPosition);}
static void Backtest(){var t=DateTimeOffset.Parse("2024-01-01T00:00:00Z");var c=new List<Candle>();for(int i=0;i<12;i++)c.Add(new(t.AddMinutes(i),10,10.1m,9.9m,10));c.Add(new(t.AddMinutes(12),10,11,9.9m,11));c.Add(new(t.AddMinutes(13),11,15,5,11));var s=new StrategySpec("x",1,2,3,1,2,new HashSet<MarketRegime>{MarketRegime.TrendingUp});var r=new DeterministicBacktester().Run(s,c);Eq(1,r.Trades.Count);if(r.Trades[0].R>=0)throw new Exception("not conservative");}
